package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;
/** Paged clan roster and invitations fit entirely within the viewport. */
final class ClanView extends View {
 interface Host {JSONObject data();String playerId();String status();void action(String type,String key,String value);void create();void invite();void member(JSONObject member);void permissions();void settings();void leave();void close();}
 private final Host host;private final Paint p=new Paint(3);private float scale,left,top;private int page=0;
 ClanView(Context c,Host h){super(c);host=h;setContentDescription("Clan roster and invitations");}
 private void text(Canvas c,String s,float x,float y,int size,int color){p.setColor(color);p.setTextSize(size);c.drawText(s,x,y,p);}
 private void box(Canvas c,float x,float y,float w,float h,int color){p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,5,5,p);}
 private JSONObject clan(){JSONObject d=host.data();return d==null?null:d.optJSONObject("clan");}
 private JSONArray rows(){JSONObject d=host.data(),c=clan();return d==null?null:c==null?d.optJSONArray("invitations"):c.optJSONArray("members");}
 protected void onDraw(Canvas c){scale=Math.min(getWidth()/960f,getHeight()/540f);left=(getWidth()-960*scale)/2;top=(getHeight()-540*scale)/2;MenuArt.get(getContext()).backdrop(c);c.save();c.translate(left,top);c.scale(scale,scale);JSONObject clan=clan();text(c,clan==null?"CLANS • Invitations":clan.optString("name"),25,40,25,0xffead5a9);text(c,"CLOSE",850,40,18,0xffead5a9);String[] labels=clan==null?new String[]{"Create clan"}:new String[]{"Invite","Permissions","Settings","Leave"};for(int i=0;i<labels.length;i++){box(c,25+i*230,65,215,40,0xff68573c);text(c,labels[i],45+i*230,92,18,Color.WHITE);}JSONArray rows=rows();int count=rows==null?0:rows.length();page=Math.min(page,Math.max(0,(count-1)/5));for(int i=0;i<5&&page*5+i<count;i++){JSONObject row=rows.optJSONObject(page*5+i);float y=122+i*62;box(c,25,y,910,55,0xff28382d);text(c,row.optString(clan==null?"name":"id"),42,y+23,18,0xffeee5cf);text(c,clan==null?"Clan invitation":row.optString("rank")+(row.optBoolean("online")?" • Online":" • Offline"),42,y+44,14,0xffb9c5b3);if(clan==null){text(c,"ACCEPT",680,y+33,18,0xffe8d2a0);text(c,"DECLINE",805,y+33,18,0xffe8d2a0);}else if(clan.optString("leader").equals(host.playerId())&&!row.optString("id").equals(host.playerId()))text(c,"MANAGE",800,y+33,18,0xffe8d2a0);}
 if(count==0)text(c,"No invitations yet. Your player ID: "+host.playerId(),35,160,18,0xffd0d6c8);text(c,"PREVIOUS",30,465,17,0xffe8d2a0);text(c,"Page "+(page+1)+" / "+Math.max(1,(count+4)/5),420,465,17,0xffe8d2a0);text(c,"NEXT",860,465,17,0xffe8d2a0);String status=host.status();text(c,status.length()>90?status.substring(0,90):status,25,510,16,0xffd0d6c8);c.restore();}
 public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()!=MotionEvent.ACTION_UP)return true;float x=(e.getX()-left)/scale,y=(e.getY()-top)/scale;if(x>=825&&y<57){host.close();return true;}JSONObject clan=clan();if(y>=65&&y<=105&&x>=25&&x<=930){int n=(int)((x-25)/230);if(clan==null){if(n==0)host.create();}else if(n==0)host.invite();else if(n==1)host.permissions();else if(n==2)host.settings();else host.leave();return true;}if(y>=438&&y<=480){if(x<160)page=Math.max(0,page-1);if(x>800)page++;invalidate();return true;}if(y>=122&&y<432){int n=page*5+(int)((y-122)/62);JSONArray rows=rows();if(rows!=null&&n<rows.length()){JSONObject row=rows.optJSONObject(n);if(clan==null&&x>=650)host.action(x<795?"clanAccept":"clanDecline","clanId",row.optString("id"));else if(clan!=null&&x>=760)host.member(row);}}return true;}
}


